"""Monthly water conservation and declared source/stock exposures; no potable-quality approval."""
from decimal import Decimal as Q
from calendar import monthrange
from food import q,ceil

def compute(cfg,food,path):
 w=cfg['water'];normal=[];drought=[];farm=q(food['farm_customer_m3']);nonfarm=q(w['household_m3'])+q(w['public_m3'])+q(w['separate_compatible_nonfood_industry_m3'])+q(food['food_potable_process_m3']);maxsource=peakstock=Q(0)
 for m,(farmweight,catchweight) in enumerate(zip(w['irrigation_month_fraction'],w['catchment_month_fraction']),1):
  days=monthrange(cfg['year'],m)[1];F=farm*q(farmweight);N=nonfarm/12;customer=F+N;sewer=F*q(w['farm_return'])+N*q(w['nonfarm_return']);recovered=sewer*q(w['recovery']);compatible=min(F,q(w['farm_reuse_max_year'])/12)+min(q(w['separate_compatible_nonfood_industry_m3'])/12,q(w['industry_reuse_max_year'])/12);reuse=min(recovered,compatible,q(w['reuse_capacity_year'])/12);fresh=customer-reuse;header=fresh/(1-q(w['network_loss']));peakstock=max(peakstock,customer/(1-q(w['network_loss']))/days*q(w['source_outage_days']))
  for multiplier,output in [(Q(1),normal),(q(w['drought_raw_fraction']),drought)]:
   rawcap=max(Q(0),q(w['raw_catchment_m3'])*multiplier-q(w['ecological_m3'])-q(w['unallocated_standby_flow_exclusion_m3']))*q(catchweight);available=rawcap*q(w['catchment_treatment_yield']);catchused=min(header,available);supp=max(Q(0),header-catchused);maxsource=max(maxsource,supp/days);process=supp*q(w['desal_kWh_product_m3'] if path=='mixed' else w['bulk_kWh_delivered_m3']);energy=(header*q(w['pump_kWh_header_m3'])+sewer*q(w['secondary_kWh_m3'])+reuse*q(w['reuse_kWh_m3'])+process)/1000000
   output.append({'month':m,'days':days,'customer_m3':customer,'farm_m3':F,'nonfarm_m3':N,'sewer_m3':sewer,'recovered_m3':recovered,'reused_m3':reuse,'compatible_reuse_sink_m3':compatible,'treated_unused_m3':recovered-reuse,'unrecovered_outflow_m3':sewer-recovered,'consumptive_m3':customer-sewer,'fresh_header_m3':header,'network_loss_m3':header-fresh,'raw_catchment_used_m3':catchused/q(w['catchment_treatment_yield']),'catchment_treatment_loss_m3':catchused/q(w['catchment_treatment_yield'])-catchused,'additional_source_m3':supp,'electricity_GWh':energy,'secondary_inside_public_meter_GWh':sewer*q(w['secondary_kWh_m3'])/1000000,'quality_and_routing':None})
 sourceunit=q(w['desal_unit_m3_day'] if path=='mixed' else w['bulk_unit_m3_day']);availability=q(w['desal_available'] if path=='mixed' else w['bulk_available']);units=max(2,ceil(maxsource/(sourceunit*availability))+1);tanks=max(w['retained_tank_count'],ceil(peakstock/(q(w['tank_gross_m3'])*q(w['tank_usable_fraction'])))+1);tankstock=q(tanks)*q(w['tank_gross_m3'])*q(w['tank_CU_m3']);newtank=(tanks-w['retained_tank_count'])*q(w['tank_gross_m3'])*q(w['tank_CU_m3']);sourcecap=q(units)*sourceunit*365*q(w['desal_capital_CU_annual_nameplate_m3']) if path=='mixed' else q(units)*q(w['bulk_terminal_each_CU']);common=q(w['reuse_stock_CU'])+q(w['leak_repair_stock_CU']);newcap=newtank+sourcecap+common;retained=q(w['retained_trunk_stock_CU'])+q(w['retained_tank_count'])*q(w['tank_gross_m3'])*q(w['tank_CU_m3']);renew=q(w['retained_trunk_stock_CU'])/q(cfg['asset_life_years']['water_retained_trunk'])+tankstock/q(cfg['asset_life_years']['tank'])+(sourcecap+common)/q(cfg['asset_life_years']['water_new'])
 continuous=(w['two_continuous_common_posts']+(units if path=='mixed' else units))*ceil(q(8760)*q('1.12')/q(cfg['continuous_task_hours']));pro=continuous+w['lab_professionals'];front=w['repair_frontline']+w['meter_frontline'];normalvolume=sum(v['additional_source_m3'] for v in normal);retainer=Q(0) if path=='mixed' else q(units)*sourceunit*365*q(w['bulk_retainer_FU_annual_nameplate_m3']);directFU=normalvolume*q(w['desal_parts_FU_m3'] if path=='mixed' else w['bulk_FU_delivered_m3'])+retainer;parts=q(w['water_other_parts_CU'])+sourcecap*q(w['source_standby_parts_fraction'])+sum(v['reused_m3'] for v in normal)*q(w['reuse_parts_CU_m3']);initialfill=q(tanks)*q(w['tank_gross_m3']);yearcap=q(units)*sourceunit*availability*365
 return {'path':path,'normal_months':normal,'drought_months':drought,'customer_m3':sum(v['customer_m3'] for v in normal),'normal_supplement_m3':normalvolume,'drought_supplement_m3':sum(v['additional_source_m3'] for v in drought),'normal_reuse_m3':sum(v['reused_m3'] for v in normal),'normal_electricity_GWh':sum(v['electricity_GWh'] for v in normal),'normal_secondary_inside_public60_GWh':sum(v['secondary_inside_public_meter_GWh'] for v in normal),'source_units':units,'unit_derated_m3_day':sourceunit*availability,'drought_peak_additional_m3_day':maxsource,'normal_new_source_annual_m3_capacity':yearcap,'one_unit_out_peak_pass':(units-1)*sourceunit*availability>=maxsource,'tank_count':tanks,'after_one_tank_lost_m3':q(tanks-1)*q(w['tank_gross_m3'])*q(w['tank_usable_fraction']),'all_fresh_and_reuse_lost_14day_peak_m3':peakstock,'stock_volume_pass':q(tanks-1)*q(w['tank_gross_m3'])*q(w['tank_usable_fraction'])>=peakstock,'retained_water_assets_CU':retained,'new_water_construction_CU':newcap,'total_asset_quote_CU':retained+newcap,'renewal_CU':renew,'professional_people':pro,'frontline_people':front,'pay_CU':q(pro)*q(cfg['pay']['professional'])+q(front)*q(cfg['pay']['frontline']),'other_parts_CU':parts,'normal_source_and_retainer_FU':directFU,'parts_import_FU':parts*q(w['parts_import_fraction'])/q(cfg['CU_per_FU']),'normal_bulk_retainer_FU':retainer,'initial_tank_fill_m3':initialfill,'initial_fill_energy_GWh':initialfill*(q(w['desal_kWh_product_m3'])+q(w['pump_kWh_header_m3']) if path=='mixed' else q(w['bulk_kWh_delivered_m3'])+q(w['pump_kWh_header_m3']))/1000000,'initial_fill_direct_FU':initialfill*q(w['desal_parts_FU_m3'] if path=='mixed' else w['bulk_FU_delivered_m3']),'new_asset_import_FU':(newtank+common)*q(cfg['asset_import_fraction']['water_common'])+sourcecap*q(cfg['asset_import_fraction']['desal'] if path=='mixed' else cfg['asset_import_fraction']['bulk']),'modeled_desal_intake_m3':normalvolume/q(w['desal_recovery']) if path=='mixed' else None,'modeled_brine_m3':normalvolume*(1/q(w['desal_recovery'])-1) if path=='mixed' else None,'actual_safe_reuse_source_independence_quality_site_and_delivery':None}
